prompt:
You are the Tester agent. The Developer produced these files for
task TASK-001 (Create a basic landing page structure):

--- index.html ---

<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>MapleSure SponsorConnect</title>
    <style>
        /* Basic CSS styling */
        body { font-family: Arial, sans-serif; margin: 0; padding: 0; }
        header, footer { background-color: #004c99; color: white; text-align: center; padding: 10px 0; }
        .container { padding: 20px; }
        .hidden { display: none; }
        form div, .confirmation-msg { margin-bottom: 15px; }
        label { display: block; margin-bottom: 5px; }
        input, select, textarea { width: 100%; padding: 8px; box-sizing: border-box; }
        button { background-color: #004c99; color: white; padding: 10px; border: none; cursor: pointer; }
        button:hover { background-color: #003366; }
    </style>
</head>
<body>
    <header>
        <h1>MapleSure Insurance</h1>
    </header>
    <div class="container">
        <form id="claim-form">
            <h2>Submit a Disability Claim</h2>
            <div>
                <label for="policy-number">Policy Number</label>
                <input type="text" id="policy-number" required>
            </div>
            <div>
                <label for="member-id">Member ID</label>
                <input type="text" id="member-id" required>
            </div>
            <div>
                <button type="button" onclick="lookupMember()">Look up member</button>
            </div>
            <div id="member-details">
                <!-- Member details panel placeholder -->
                <p>Member details will appear here after lookup.</p>
            </div>
            <div>
                <label for="last-day-worked">Last Day Worked</label>
                <input type="date" id="last-day-worked" required>
            </div>
            <div>
                <label for="first-day-absent">First Day Absent</label>
                <input type="date" id="first-day-absent" required>
            </div>
            <div>
                <label for="nature-of-absence">Nature of Absence</label>
                <select id="nature-of-absence" required>
                    <option value="">Select...</option>
                    <option value="illness">Illness</option>
                    <option value="injury">Injury</option>
                    <option value="personal">Personal</option>
                </select>
            </div>
            <div>
                <label for="details">Details</label>
                <textarea id="details" rows="4"></textarea>
            </div>
            <div>
                <label for="documents">Upload Documents</label>
                <input type="file" id="documents" multiple onchange="updateFileList()">
                <ul id="file-list"></ul>
            </div>
            <button type="submit" onclick="submitForm(event)">Submit Claim</button>
        </form>
        <div id="confirmation" class="hidden">
            <h2>Claim Submission</h2>
            <p class="confirmation-msg">Reference Number: <span id="ref-number"></span></p>
            <p class="confirmation-msg">Status: Received</p>
        </div>
    </div>
    <footer>
        <p>MapleSure Insurance — fictional demo application</p>
    </footer>

    <script>
        // Mock data object for member lookup
        const mockMembers = {
            "12345": "John Doe",
            "67890": "Jane Smith"
        };

        function lookupMember() {
            const memberId = document.getElementById('member-id').value;
            const memberDetails = document.getElementById('member-details');

            if (mockMembers[memberId]) {
                memberDetails.innerHTML = `<p>Member Name: ${mockMembers[memberId]}</p>`;
            } else {
                memberDetails.innerHTML = '<p>Member not found.</p>';
            }
        }

        function updateFileList() {
            const input = document.getElementById('documents');
            const fileList = document.getElementById('file-list');

            fileList.innerHTML = '';
            for (let i = 0; i < input.files.length; i++) {
                const li = document.createElement('li');
                li.textContent = input.files[i].name;
                fileList.appendChild(li);
            }
        }

        function submitForm(event) {
            event.preventDefault();
            const form = document.getElementById('claim-form');
            form.classList.add('hidden');

            const confirmation = document.getElementById('confirmation');
            confirmation.classList.remove('hidden');
            document.getElementById('ref-number').textContent = generateReferenceNumber();
        }

        function generateReferenceNumber() {
            const date = new Date();
            const year = date.getFullYear();
            const month = ('0' + (date.getMonth() + 1)).slice(-2);
            const randomPart = Math.floor(1000 + Math.random() * 9000);
            return `MS-${year}-${month}-${randomPart}`;
        }
    </script>
</body>
</html>


Acceptance criteria:
- US-1-AC1: Given an anonymous or authenticated advisor, when navigating to '/', then the page shows the MapleSure branded header and footer.
- US-1-AC2: Given an anonymous or authenticated advisor, when navigating to '/', then the page structure is present with placeholder text and elements.

Write pytest tests (a single test_app.py) that verify the happy path
STRUCTURALLY against the actual file above — read index.html from
Path(__file__).parent and assert what the criteria need: the form and its
required field ids exist, the upload input allows multiple files, the
confirmation panel and status markup exist, the member lookup mock data is
present. 4 to 6 focused tests, stdlib + pytest only, no browser, no server,
no network. Every assertion must hold for the file exactly as shown above,
and must be independent of the current date, time, or environment — never
hard-code a year, month, or timestamp; where the page generates a value at
runtime, assert the generating code exists, not the value it would produce
today.

JSON schema: {"files": [{"path": "test_app.py", "content": str}]}
